 {
 	bk_err_t	ret_code;

 	u8		phy_chnl_idx = GET_DST_CPU_ID(log_chnl);   // = DST_CPU_ID;
 	u8		log_chnl_idx = GET_LOG_CHNL_ID(log_chnl);

